import React from 'react';
import './TodoList.css';
import TodoItem from './TodoItem';

const TodoList = ({ todos, onUpdateTodo, onDeleteTodo, onToggleTodo }) => {
  if (todos.length === 0) {
    return (
      <div className="empty-state">
        <div className="empty-icon">✨</div>
        <h3>No todos for this date</h3>
        <p>All done or just getting started?</p>
      </div>
    );
  }

  // Sort todos by status
  const statusOrder = { 'yet_to_start': 0, 'in_progress': 1, 'completed': 2 };
  const priorityOrder = { high: 0, medium: 1, low: 2 };
  const sortedTodos = [...todos].sort((a, b) => {
    const statusA = statusOrder[a.status] || 3;
    const statusB = statusOrder[b.status] || 3;
    if (statusA !== statusB) return statusA - statusB;

    const priorityA = priorityOrder[a.priority] || 3;
    const priorityB = priorityOrder[b.priority] || 3;
    return priorityA - priorityB;
  });

  const completedTodos = sortedTodos.filter(t => t.status === 'completed');
  const inProgressTodos = sortedTodos.filter(t => t.status === 'in_progress');
  const yetToStartTodos = sortedTodos.filter(t => t.status === 'yet_to_start');

  return (
    <div className="todo-list">
      {/* Yet to Start Todos */}
      {yetToStartTodos.length > 0 && (
        <div className="todo-section yet-to-start">
          <h4 className="section-title">⭕ Yet to Start ({yetToStartTodos.length})</h4>
          <div className="todos-container">
            {yetToStartTodos.map(todo => (
              <TodoItem
                key={todo.id}
                todo={todo}
                onUpdateTodo={onUpdateTodo}
                onDeleteTodo={onDeleteTodo}
                onToggleTodo={onToggleTodo}
              />
            ))}
          </div>
        </div>
      )}

      {/* In Progress Todos */}
      {inProgressTodos.length > 0 && (
        <div className="todo-section in-progress">
          <h4 className="section-title">⏳ In Progress ({inProgressTodos.length})</h4>
          <div className="todos-container">
            {inProgressTodos.map(todo => (
              <TodoItem
                key={todo.id}
                todo={todo}
                onUpdateTodo={onUpdateTodo}
                onDeleteTodo={onDeleteTodo}
                onToggleTodo={onToggleTodo}
              />
            ))}
          </div>
        </div>
      )}

      {/* Completed Todos */}
      {completedTodos.length > 0 && (
        <div className="todo-section completed">
          <h4 className="section-title">✅ Completed ({completedTodos.length})</h4>
          <div className="todos-container">
            {completedTodos.map(todo => (
              <TodoItem
                key={todo.id}
                todo={todo}
                onUpdateTodo={onUpdateTodo}
                onDeleteTodo={onDeleteTodo}
                onToggleTodo={onToggleTodo}
              />
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default TodoList;
